select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'works:1' as ref,(select to_jsonb(t) from public.works t where t.id=987139006)='{"id":987139006,"title":"La Peste","cover_id":null,"author_id":977300023,"work_type":null,"source_type":"open_library","open_library_id":"OL1230715W","first_publish_year":1947,"native_identity_key":"nlscale:fixture040:423"}'::jsonb as exact union all select 'editions:2' as ref,(select to_jsonb(t) from public.editions t where t.id=987239020)='{"id":987239020,"title":"De pest","isbn_10":null,"isbn_13":"9789023428756","work_id":987139006,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL59692847M"}'::jsonb as exact union all select 'catalog_work_descriptions:3' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139006 and t.language='nl')='{"text":"Een pestepidemie grijpt om zich heen in de Algerijnse stad Oran. Het gewone leven raakt ontwricht en bewoners worden gedwongen zich tot de dreiging te verhouden. Artsen en andere inwoners reageren vanuit uiteenlopende belangen, angsten en overtuigingen. De roman volgt hoe afzondering en onzekerheid hun gedrag veranderen. Albert Camus gebruikt de ziekte als aanleiding om te onderzoeken wat mensen tegenover rampspoed kunnen stellen en welke betekenis verantwoordelijkheid krijgt wanneer niemand zich eenvoudig aan de omstandigheden kan onttrekken.","work_id":987139006,"evidence":[{"note":"LaPeste1947, exactDutch DePest9789023428756. CurrentWorkyear1942 is not first publication; two exactKB originals and physical original-edition bibliography confirm1947.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p30757248X","http://data.bibliotheken.nl/id/nbt/p409124710"],"reference":"work:423","checked_a