b(t) from public.editions t where t.id=987239021)='{"id":987239021,"title":"Macbeth","isbn_10":null,"isbn_13":"9789064032295","work_id":987139004,"cover_id":null,"language":"dut","publisher":"International Theatre & Film Books","publish_date":null,"open_library_edition_id":"OL34490134M"}'::jsonb as exact union all select 'catalog_work_descriptions:7' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139004 and t.language='nl')='{"text":"Macbeth is een gerespecteerde legeraanvoerder wanneer een voorspelling zijn verlangen naar macht versterkt. Aangemoedigd door zijn vrouw besluit hij een grens over te gaan om de kroon te bereiken. De verkregen positie brengt hem echter geen zekerheid. Angst voor verlies en wantrouwen leiden tot nieuwe gewelddadige keuzes. Het toneelstuk volgt hoe ambitie steeds meer van zijn denken en handelen gaat bepalen, totdat de macht die hij zocht zijn bestaan volledig beheerst.","work_id":987139004,"evidence":[{"note":"Complete Dutch theatre text Macbeth9789064032295, not a prose retelling or English edition. Folger confirms first PRINT publication1623, distinguish composition circa1606; current1508 is impossible. Worktype/taste features unchanged.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p05864119X"],"reference":"work:323","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://www.folger.edu/explore/shakespeares-works/macbeth/an-introduction-to-this-text/","https://openlibrary.org/works/OL258902W","https://data.bibliotheken.nl/id/nbt/p05864119X"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789064032295","status":"no_verifi