l":"https://data.bibliotheken.nl/id/nbt/p435656155","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987339005}'::jsonb as exact union all select 'editions:18' as ref,(select to_jsonb(t) from public.editions t where t.id=987239025)='{"id":987239025,"title":"Inferno","isbn_10":null,"isbn_13":"9789024561858","work_id":987139010,"cover_id":null,"language":"dut","publisher":"Uitgeverij Luitingh-Sijthoff","publish_date":null,"open_library_edition_id":"OL25429536M"}'::jsonb as exact union all select 'catalog_work_descriptions:19' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139010 and t.language='nl')='{"text":"Robert Langdon raakt in Italië betrokken bij een raadsel dat verwijst naar Dantes Inferno. Zijn kennis van symbolen en kunst wordt onmisbaar, maar verklaart niet meteen wie hem tegenover zich heeft. Aanwijzingen voeren langs historische plaatsen en verbinden oude voorstellingen met nieuwe wetenschappelijke mogelijkheden. Langdon moet onder tijdsdruk bepalen welke informatie betrouwbaar is en wie hij kan vertrouwen. Wat begint als een zoektocht naar betekenis, blijkt gevolgen te kunnen hebben die veel verder reiken dan het literaire raadsel.","work_id":987139010,"evidence":[{"note":"DanBrownInferno2013 RobertLangdon, exactDutchpaperback9789024561858; remove n/a from source publisher via exactKB publication UitgeverijLuitinghSijthoff. No Dante original or film Work merge.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p37471424X","http://data.bibliotheken.nl/id/nbt/p374715149","http://data.bibliotheken.nl/id/nbt/p374715262","http://data.bibliotheken.nl/id/nbt/p370098315","http://data.bibliotheken.nl/id/nbt/p370098447","http://data.bibliotheken.nl/id/nbt/p370098552","http://data.bibliotheken.nl/id/nbt/p370098617","http://data.bibliotheken.nl/id/nbt/p37009865X"],"reference":"work:559","checked_at":"2026-11