6M"}'::jsonb as exact union all select 'catalog_work_descriptions:25' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139011 and t.language='nl')='{"text":"De elfjarige Mark Sway hoort na een onverwachte ontmoeting informatie over een moordzaak. Daarmee komt hij klem te zitten tussen de autoriteiten, die hem willen laten praten, en criminelen die juist zijn stilzwijgen nodig hebben. Hij zoekt hulp bij advocaat Reggie Love. Zij probeert hem te beschermen zonder de dreiging uit het oog te verliezen. Het verhaal volgt hoe een kind een geheim moet dragen dat volwassenen met veel meer macht ieder op hun eigen manier willen beheersen.","work_id":987139011,"evidence":[{"note":"JohnGrisham TheClient1993 MarkSway/ReggieLove, exactfullDutchpaperback9789022981948, notReadersDigest abridgement orfilm.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p124872301"],"reference":"work:561","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-017.json","sources":["http://www.jgrisham.com/books/the-client/","https://openlibrary.org/works/OL77022W","https://data.bibliotheken.nl/id/nbt/p124872301"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789022981948","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":11015814,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL32366726M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"la