nce_url":"https://data.bibliotheken.nl/id/nbt/p124872301","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987339006}'::jsonb as exact union all select 'editions:27' as ref,(select to_jsonb(t) from public.editions t where t.id=987239028)='{"id":987239028,"title":"Gender Queer","isbn_10":null,"isbn_13":"9789002277986","work_id":987139017,"cover_id":null,"language":"dut","publisher":"Davidsfonds Infodok","publish_date":null,"open_library_edition_id":"OL60598610M"}'::jsonb as exact union all select 'catalog_work_descriptions:28' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139017 and t.language='nl')='{"text":"Maia Kobabe vertelt in stripvorm over het zoeken naar woorden voor genderidentiteit en seksualiteit. Herinneringen aan opgroeien, verliefdheden en vriendschappen laten zien hoe dat begrip zich geleidelijk ontwikkelde. Ook gesprekken met familie en ervaringen rond lichamelijkheid krijgen een plaats. Het boek ontstond mede uit de behoefte uit te leggen wat non-binair en aseksueel voor de auteur betekenen. De persoonlijke vorm maakt zichtbaar hoeveel vragen en onzekerheden achter ogenschijnlijk eenvoudige categorieën kunnen schuilgaan.","work_id":987139017,"evidence":[{"note":"MaiaKobabe2019 graphicmemoir, exact Dutch9789002277986. Personal nonbinary/asexual narrative, not a medical textbook or conventional novel; no type/taste inference.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p438685180"],"reference":"work:854","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-017.json","sources":["https://openlibrary.org/works/OL21337755W","https://data.bibliotheken.nl/id/nbt/p438685180"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actu