as exact union all select 'works:45' as ref,(select to_jsonb(t) from public.works t where t.id=987139012)='{"id":987139012,"title":"Tell No One","cover_id":null,"author_id":987304003,"work_type":null,"source_type":"open_library","open_library_id":"OL79319W","first_publish_year":2001,"native_identity_key":"nlscale:fixture040:585"}'::jsonb as exact union all select 'editions:46' as ref,(select to_jsonb(t) from public.editions t where t.id=987239034)='{"id":987239034,"title":"Niemand vertellen","isbn_10":null,"isbn_13":"9789022530450","work_id":987139012,"cover_id":null,"language":"dut","publisher":"De Boekerij","publish_date":null,"open_library_edition_id":"OL45867977M"}'::jsonb as exact union all select 'catalog_work_descriptions:47' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139012 and t.language='nl')='{"text":"Acht jaar na de dood van zijn vrouw Elizabeth ontvangt arts David Beck een anoniem bericht met een verwijzing die alleen zij samen kenden. Een beeld op internet lijkt vervolgens te tonen dat Elizabeth nog leeft. Zijn poging te begrijpen wat hij ziet, opent het oude onderzoek opnieuw. Tegelijk krijgt hij zelf te maken met verdenkingen en gevaar. Beck moet bepalen of het bericht hoop biedt of onderdeel is van iets dat de herinnering aan hun laatste gezamenlijke dag bewust manipuleert.","work_id":987139012,"evidence":[{"note":"CobenTellNoOne2001, exactDutchNiemandVertellen9789022530450; currentWorkyear2000 conflicts with exactKBoriginalDelacorte2001 and publishercolophon. Preserve sameexistingWork, notFrenchfilm.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p237530015"],"reference":"work:585","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://www.hugendubel.info/annot/564C42696D677C7C393738333434323438323635387C7C504446.pdf?sq=1","h