act union all select 'catalog_work_descriptions:53' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987139014 and t.language='nl')='{"text":"Myron Bolitar heeft een tiener beloofd dat zij hem altijd mag bellen als ze hulp nodig heeft. Wanneer Aimee midden in de nacht contact opneemt, haalt hij haar op en zet haar op haar verzoek bij een onbekend adres af. Daarna verdwijnt ze. Schuldgevoel en bezorgdheid brengen hem ertoe zelf naar haar te zoeken. Hij moet uitzoeken wat er achter het ogenschijnlijk eenvoudige verzoek schuilging en welke gevolgen zijn goedbedoelde tussenkomst heeft gehad.","work_id":987139014,"evidence":[{"note":"CobenPromiseMe2006 MyronBolitar/Aimee, exactDutchEensBeloofd9789022564240; not an anonymous same-title novel, no new series linkage guessed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p343312166"],"reference":"work:627","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://openlibrary.org/works/OL79329W","https://data.bibliotheken.nl/id/nbt/p343312166"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789022564240","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15160197,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL40205682M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"