ntstaat toenadering, maar hun contact verloopt moeizaam doordat Victoria zich nauwelijks kan uiten. Sylvia krijgt steeds sterker het gevoel dat haar patiënte iets belangrijks probeert duidelijk te maken. Wat een overzichtelijke zorgtaak leek, roept daardoor steeds meer vragen op over het huishouden waarin zij terechtgekomen is.","work_id":987139013,"evidence":[{"note":"FreidaMcFadden TheWifeUpstairs2020 Victoria/Sylvia, exactDutchDeVrouwOpZolder9789032521479. Distinct fromRachelHawkins identically titled2021novel; no inferred author merge.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p444714715"],"reference":"work:589","checked_at":"2026-11-03T08:16:03.676Z","supplemental":null,"existingAlternativeReview":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL26121595W","https://data.bibliotheken.nl/id/nbt/p444714715"]},{"note":"Exact bounded bulk source did not provide a verified asset; reuse unchanged resolver and inspect actual front or neutral placeholder hosted. No arbitrary image or absent-book claim.","type":"no_verified_cover_asset_retained","isbn13":"9789032521479","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15158672,"receipt":"cover-archive-v2-readback.json","receiptSha256":"8529a8efea33798915ea378cecc82a7765e1800b8ec34536875c4a996d541fc7"}],"checkedAt":"2026-11-03T08:16:03.677Z","editionKey":"/books/OL61057863M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL26121595W","reviewed_at":"2026-11-03T08:16:03.676+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-040","review_status":"approved","bound_author_id":